contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount) public payable {
        require(address(this).balance >= amount, "insufficient balance");

        bytes32 guess = keccak256(abi.encodePacked(uint256(0)));
        c.lockInGuess{value: 1 ether}(guess);

        uint256 balBefore = address(c).balance;
        uint256 senderBefore = address(this).balance;

        bool reverted;
        try c.settle() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 balAfter = address(c).balance;
        uint256 senderAfter = address(this).balance;

        assert(
            balAfter * senderAfter == balBefore * senderBefore ||
            (balBefore >= 2 ether && balAfter == balBefore - 2 ether && senderAfter == senderBefore + 2 ether)
        );
    }

    receive() external payable {}
}

